query ShippingRefundAgreements($source: ID!, $after: String) {
  order(id: $source) {
    agreements(first: 50, after: $after) {
      nodes {
        __typename
        id
        happenedAt
        reason
        app { id }
        ... on RefundAgreement {
          refund { id }
        }
      }
      pageInfo { hasNextPage endCursor }
    }
  }
}
